#!/usr/bin/env python3
"""Generate hard_extra.json for the 8 exams whose hard tier is below 100.

Reads each exam's master hard.json for header metadata (never invents
exam_name / exam_code / duration_minutes / live_exam_question_count), and
writes questions in the master's exact key order so no reordering pass is
needed afterwards. Sources are NOT modified; output goes to hard_extra.json.
"""
import json

B = "apps/web/question-bank"


def emit(exam, prefix, start, rows, target=100):
    meta = json.load(open(f"{B}/{exam}/hard.json", encoding="utf-8"))
    qs, n = [], start
    for r in rows:
        qs.append({
            "domain": r[0],
            "difficulty": "hard",
            "question": r[1],
            "options": {"A": r[2], "B": r[3], "C": r[4], "D": r[5]},
            "correct_answer": [r[6]],
            "explanation": r[7],
            "id": f"{prefix}-{n:04d}",
            "type": "MCQ",
        })
        n += 1
    out = {
        "exam_name": meta["exam_name"],
        "exam_code": meta["exam_code"],
        "duration_minutes": meta["duration_minutes"],
        "live_exam_question_count": meta["live_exam_question_count"],
        "difficulty_tier": "hard",
        "questions_in_this_file": len(qs),
        "target_for_tier": target,
        "last_updated": "2026",
        "questions": qs,
    }
    with open(f"{B}/{exam}/hard_extra.json", "w", encoding="utf-8") as fh:
        json.dump(out, fh, indent=2, ensure_ascii=False)
        fh.write("\n")
    total = len(meta["questions"]) + len(qs)
    print(f"{exam}: wrote {len(qs)} Qs ({qs[0]['id']}..{qs[-1]['id']}) -> hard total {total}")


